1	import { pvpGoldTransfer, rubbingTypeSchema, type RubbingType } from "@pirate-sea-race/content/objectives";
2	import {
3	  atTick,
4	  isPlayerId,
5	  moveRubbings,
6	  noEffects,
7	  playerRejection,
8	  releaseTo,
9	  tickRejection,
10	  updatePlayer,
11	  type Effects,
12	  type LedgerRejection,
13	  type LedgerStep,
14	  type Transfer,
15	} from "./internal.js";
16	import {
17	  activeDuelOf,
18	  byTypeOrder,
19	  defaultTheftType,
20	  eligibleTheftTypes,
21	  findDuel,
22	  findPlayer,
23	  reservedIn,
24	  type DuelResultRecord,
25	  type DuelSettlement,
26	  type LedgerDuel,
27	  type LedgerState,
28	} from "./state.js";
29	
30	export interface DuelResult {
31	  readonly ok: boolean;
32	  readonly rejection: LedgerRejection | null;
33	  /** The duel as it now stands (its current result for a rejected request), or null for an unknown duel. */
34	  readonly duel: LedgerDuel | null;
35	  readonly transfers: readonly Transfer[];
36	  readonly cacheIds: readonly string[];
37	}
38	
39	function rejected(state: LedgerState, rejection: LedgerRejection, duelId: unknown): LedgerStep<DuelResult> {
40	  const duel = typeof duelId === "string" ? (findDuel(state, duelId) ?? null) : null;
41	  return { state, result: { ok: false, rejection, duel, transfers: [], cacheIds: [] } };
42	}
43	
44	function applied(state: LedgerState, duelId: string, effects: Effects): LedgerStep<DuelResult> {
45	  return {
46	    state,
47	    result: { ok: true, rejection: null, duel: findDuel(state, duelId) ?? null, ...effects },
48	  };
49	}
50	
51	function replaceDuel(state: LedgerState, duel: LedgerDuel): LedgerState {
52	  return { ...state, duels: state.duels.map((existing) => (existing.id === duel.id ? duel : existing)) };
53	}
54	
55	export interface ReserveDuelRequest {
56	  /** Created by the server for the encounter. */
57	  readonly duelId: string;
58	  readonly players: readonly [string, string];
59	  readonly tick: number;
60	}
61	
62	/**
63	 * Reserves both players' rubbings inside the duel (§4, §16), so none of them can be collected, stolen or abandoned
64	 * twice while it runs, and cancels both players' channels. A disconnected player can be challenged (§12).
65	 */
66	export function reserveDuel(state: LedgerState, request: ReserveDuelRequest): LedgerStep<DuelResult> {
67	  const { duelId, players, tick } = request;
68	  const bad = tickRejection(state, tick);
69	  if (bad) return rejected(state, bad, duelId);
70	  if (!isPlayerId(duelId) || !Array.isArray(players) || players.length !== 2) return rejected(state, "invalid-request", duelId);
71	  if (findDuel(state, duelId)) return rejected(state, "duplicate", duelId);
72	  const [a, b] = players;
73	  if (a === b) return rejected(state, "same-player", duelId);
74	  for (const playerId of players) {
75	    const refusal = playerRejection(state, playerId) ?? (activeDuelOf(state, playerId) ? "player-in-duel" : null);
76	    if (refusal) return rejected(state, refusal, duelId);
77	  }
78	  const effects = noEffects();
79	  const duel: LedgerDuel = {
80	    id: duelId,
81	    players: [a, b],
82	    startTick: tick,
83	    phase: "fighting",
84	    result: null,
85	    choiceDeadline: null,
86	    settlement: null,
87	  };
88	  let next: LedgerState = { ...atTick(state, tick), duels: [...state.duels, duel] };
89	  for (const playerId of players) next = updatePlayer(next, playerId, (player) => ({ ...player, channel: null }));
90	  next = moveRubbings(
91	    next,
92	    next.rubbings.flatMap((rubbing) =>
93	      rubbing.location.kind === "player" && players.includes(rubbing.location.playerId)
94	        ? [{ rubbingId: rubbing.id, to: { kind: "duel", duelId, playerId: rubbing.location.playerId } as const }]
95	        : [],
96	    ),
97	    effects,
98	  );
99	  return applied(next, duelId, effects);
100	}
101	
102	export interface ReportDuelResultRequest {
103	  readonly duelId: string;
104	  readonly tick: number;
105	  /** `cancelled`: both players forfeited on the same tick (§12), which settles like a draw. */
106	  readonly outcome: "win" | "draw" | "cancelled";
107	  /** The winner, for `win` only. */
108	  readonly winner?: string;
109	}
110	
111	/**
112	 * Records the fight's result once. A draw or cancellation settles at once with nothing moving. A win opens the
113	 * winner's theft choice window, or settles at once (gold only) when no type is eligible. Any later result message
114	 * for the duel, even a different one, changes nothing and returns the current result.
115	 */
116	export function reportDuelResult(state: LedgerState, request: ReportDuelResultRequest): LedgerStep<DuelResult> {
117	  const { duelId, tick, outcome, winner } = request;
118	  const bad = tickRejection(state, tick);
119	  if (bad) return rejected(state, bad, duelId);
120	  const duel = typeof duelId === "string" ? findDuel(state, duelId) : undefined;
121	  if (!duel) return rejected(state, "unknown-duel", duelId);
122	  if (duel.phase !== "fighting") return rejected(state, "already-resolved", duelId);
123	  if (outcome === "win") {
124	    if (winner === undefined || !duel.players.includes(winner)) return rejected(state, "not-a-participant", duelId);
125	  } else if ((outcome !== "draw" && outcome !== "cancelled") || winner !== undefined) {
126	    return rejected(state, "invalid-request", duelId);
127	  }
128	  const effects = noEffects();
129	  const next = recordResult(atTick(state, tick), duel, outcome, winner ?? null, false, tick, effects);
130	  return applied(next, duelId, effects);
131	}
132	
133	/** Records a result for a duel still fighting; shared with a forfeit by a player who leaves. */
134	export function recordResult(
135	  state: LedgerState,
136	  duel: LedgerDuel,
137	  outcome: DuelResultRecord["outcome"],
138	  winner: string | null,
139	  forfeit: boolean,
140	  tick: number,
141	  effects: Effects,
142	): LedgerState {
143	  if (outcome !== "win") {
144	    const result: DuelResultRecord = { outcome, winner: null, loser: null, forfeit: false, tick };
145	    const settlement: DuelSettlement = {
146	      tick,
147	      stolenRubbingId: null,
148	      stolenType: null,
149	      choice: "none",
150	      gold: 0,
151	      goldSuppressed: false,
152	    };
153	    let next = replaceDuel(state, { ...duel, phase: "settled", result, settlement });
154	    for (const playerId of duel.players) {
155	      next = releaseTo(next, playerId, reservedIn(next, duel.id, playerId).map((rubbing) => rubbing.id), tick, effects);
156	    }
157	    return next;
158	  }
